"""Brute-force reference for the planner: exhaustive subset search."""
import itertools, json, random, subprocess, sys

CAND = '/workspace/submission/main.py'

def brute(caps, flows, warmup, pinned, offers):
    ids = list(flows)
    def benefit(fid):
        f = flows[fid]
        H = len(bytes.fromhex(f['template']))
        kinds = f['kinds']
        N = len(f['path'])
        d = kinds.count('D')
        per = (H - 4 - d) * N
        rem = warmup
        elig = 0
        for run in offers[fid]:
            c = run['count']
            if rem >= c:
                rem -= c
                continue
            fresh = c - rem
            rem = 0
            hdr = bytes.fromhex(run['header'])
            tmpl = bytes.fromhex(f['template'])
            ok = all(hdr[i] == tmpl[i] for i,ch in enumerate(kinds) if ch=='K')
            q = kinds.index('Q'); t = kinds.index('T')
            if ok and hdr[q] <= 7 and hdr[t] > N-1:
                elig += fresh
        return per * elig
    bens = {fid: benefit(fid) for fid in ids}
    pin = set(pinned)
    # feasibility of pinned alone
    use = {}
    for fid in pin:
        for n in flows[fid]['path']:
            use[n] = use.get(n,0)+1
    for n,c in use.items():
        if c > caps[n]:
            return {'infeasible': True}
    best = None
    others = [f for f in ids if f not in pin]
    for k in range(len(others)+1):
        for combo in itertools.combinations(others, k):
            sel = set(combo) | pin
            use = {}
            for fid in sel:
                for n in flows[fid]['path']:
                    use[n] = use.get(n,0)+1
            if any(c > caps[n] for n,c in use.items()):
                continue
            b = sum(bens[f] for f in sel)
            cand = (b, -len(sel))
            if best is None or cand > best:
                best = cand
    if best is None:
        return {'infeasible': True}
    return {'saved': best[0], 'selected': sorted(pin)}  # placeholder

def gen(rng):
    nnodes = rng.randint(1,4)
    nodes = ['n%d'%i for i in range(nnodes)]
    caps = {n: rng.randint(0,3) for n in nodes}
    nflows = rng.randint(0,6)
    flows = []
    ids = []
    for i in range(nflows):
        fid = 'f%d'%i
        ids.append(fid)
        L = rng.randint(8,12)
        path = rng.sample(nodes, rng.randint(1,min(3,nnodes)))
        kinds = ['K']*L
        kinds[rng.randrange(L)] = 'Q'
        kinds[rng.randrange(L)] = 'T'
        for _ in range(rng.randint(0,L-1)):
            kinds[rng.randrange(L)] = rng.choice('DZ')
        while kinds.count('Q') != 1 or kinds.count('T') != 1:
            break
        # ensure exactly one Q one T distinct
        qs = [j for j,ch in enumerate(kinds) if ch=='Q']
        ts = [j for j,ch in enumerate(kinds) if ch=='T']
        if len(qs)!=1 or len(ts)!=1:
            kinds = ['K']*L
            kinds[0]='Q'; kinds[1]='T'
        tmpl = bytes(rng.randrange(256) for _ in range(L)).hex()
        flows.append(dict(id=fid,path=path,template=tmpl,kinds=''.join(kinds)))
    warmup = rng.choice([0,1,3])
    offers = {}
    for f in flows:
        runs = []
        for _ in range(rng.randint(0,3)):
            H = len(f['template'])//2
            hdr = bytes.fromhex(f['template'])
            hdr = bytearray(hdr)
            # random mutate some bytes
            for _ in range(rng.randint(0,2)):
                hdr[rng.randrange(H)] = rng.randrange(256)
            runs.append(dict(header=bytes(hdr).hex(), count=rng.randint(1,20)))
        offers[f['id']] = runs
    pinned = rng.sample(ids, rng.randint(0, min(2,len(ids))))
    return dict(mode='plan',capacities=caps,flows=flows,warmup=warmup,pinned=pinned,offers=offers)

def main():
    rng = random.Random(int(sys.argv[1]) if len(sys.argv)>1 else 1)
    bad = 0
    for it in range(int(sys.argv[2]) if len(sys.argv)>2 else 200):
        req = gen(rng)
        line = json.dumps(req)+'\n'
        out = subprocess.run([sys.executable,'-I','-B',CAND],input=line,text=True,capture_output=True)
        got = json.loads(out.stdout.splitlines()[0])
        exp = brute(req['capacities'], req['flows'], req['warmup'], req['pinned'], req['offers'])
        if exp.get('infeasible'):
            if got != {'infeasible': True}:
                print('MISMATCH infeasible', it, got, exp); bad+=1; print(json.dumps(req)); break
            continue
        if 'saved' in exp:
            # recompute: brute enumerate all max-benefit, min-count sets
            ids = list(req['flows'][i]['id'] for i in range(len(req['flows'])))
            bestb = exp['saved']
            # our brute function already maximized (benefit, -count)
            # find any set achieving that
            import itertools
            found = None
            for k in range(len(ids)+1):
                for combo in itertools.combinations(ids, k):
                    sel = set(combo)
                    if not set(req['pinned']) <= sel: continue
                    use = {}
                    for fid in sel:
                        for n in req['flows'][ids.index(fid)]['path']:
                            use[n]=use.get(n,0)+1
                    if any(c > req['capacities'][n] for n,c in use.items()): continue
                    b = 0
                    for fid in sel:
                        f = req['flows'][ids.index(fid)]
                        H = len(bytes.fromhex(f['template'])); N=len(f['path'])
                        per = (H-4-f['kinds'].count('D'))*N
                        rem = req['warmup']; elig=0
                        for run in req['offers'][fid]:
                            c=run['count']
                            if rem>=c: rem-=c; continue
                            fresh=c-rem; rem=0
                            hdr=bytes.fromhex(run['header']); tmpl=bytes.fromhex(f['template'])
                            ok=all(hdr[i]==tmpl[i] for i,ch in enumerate(f['kinds']) if ch=='K')
                            q=f['kinds'].index('Q'); t=f['kinds'].index('T')
                            if ok and hdr[q]<=7 and hdr[t]>N-1: elig+=fresh
                        b += per*elig
                    if b==bestb and (found is None or len(sel)<len(found)):
                        found=sel
            if 'saved' not in got or got['saved']!=bestb:
                print('MISMATCH benefit', it, got, bestb); bad+=1; print(json.dumps(req)); break
            if len(got.get('selected',[])) != len(found):
                print('MISMATCH count', it, got, len(found)); bad+=1; print(json.dumps(req)); break
            if set(req['pinned']) - set(got.get('selected',[])):
                print('MISMATCH pinned', it, got); bad+=1; break
    print('done, bad =', bad)

main()
